void DiffState::display(int coreid) {
  Info("\n============== Commit Group Trace (Core %d) ==============\n", coreid);
  for (int j = 0; j < DEBUG_GROUP_TRACE_SIZE; j++) {
    display_commit_count(j);
  }

  Info("\n============== Commit Instr Trace ==============\n");
  bool use_spike = spike_valid();
  for (int j = 0; j < DEBUG_INST_TRACE_SIZE; j++) {
    display_commit_instr(j, use_spike);
  }

  fflush(stdout);

bool spike_valid() {
  if (!is_tested) {
    is_tested = true;
    char cmd[128];
    sprintf(cmd, "%s > /dev/null 2> /dev/null", dasm_cmd);
    is_valid = !system(cmd);
  }
  return is_valid;
}

static void execute_dasm_cmd() {
  FILE *ptr = popen(dasm_cmd, "r");
  if (ptr) {
    fgets(dasm_result, sizeof(dasm_result), ptr);

  // cycle limitation
  bool exceed_cycle_limit = false;
#ifdef CONFIG_NO_DIFFTEST
  exceed_cycle_limit = !args.max_cycles;
#else
  for (int i = 0; i < NUM_CORES; i++) {
    auto trap = difftest[i]->get_trap_event();
    if (trap->cycleCnt >= args.max_cycles) {
      exceed_cycle_limit = true;
    }
  }
#endif // CONFIG_NO_DIFFTEST

  if (exceed_cycle_limit) {
    trapCode = STATE_LIMIT_EXCEEDED;
#ifdef FUZZER_LIB
    stats.exit_code = SimExitCode::exceed_limit;
#endif // FUZZER_LIB
    return trapCode;
